import json
import subprocess
import sys
import unittest
from pathlib import Path

from flow import load_flows, render


def load(name):
    return load_flows(Path(name))


class TestLoading(unittest.TestCase):
    def test_flow_pairs_the_disagreement_with_its_hypotheses(self):
        [flow] = load("sample_flow.json")
        self.assertEqual(flow["a"]["sender"], "researcher")
        self.assertEqual(flow["b"]["sender"], "engineer")
        self.assertEqual(flow["outcome"]["resolution"], "RESOLVED_BY_EXPERIMENT")

    def test_the_winner_is_identified_by_message_id(self):
        [flow] = load("sample_flow.json")
        self.assertEqual(flow["winner_side"], "a")

    def test_an_unresolved_flow_has_no_winner(self):
        [flow] = load("sample_unresolved.json")
        self.assertIsNone(flow["winner_side"])

    def test_an_exchange_without_disagreements_yields_no_flows(self):
        Path("plain.json").write_text(json.dumps({"messages": [], "disagreements": []}),
                                      encoding="utf-8")
        self.assertEqual(load("plain.json"), [])


class TestRendering(unittest.TestCase):
    def _html(self, name="sample_flow.json", title="demo"):
        return render(load(name), title=title)

    def test_both_hypotheses_and_their_agents_appear(self):
        html = self._html()
        self.assertIn("researcher", html)
        self.assertIn("engineer", html)
        self.assertIn("the migration dropped cust_idx", html)

    def test_content_is_escaped(self):
        html = self._html()
        self.assertNotIn("<i>per-item</i>", html)
        self.assertIn("&lt;i&gt;per-item&lt;/i&gt;", html)

    def test_the_ladder_stages_are_visible_in_order(self):
        """The process is the subject: hypotheses, then the predictions made
        BEFORE the run, then the observation, then the verdict."""
        html = self._html().lower()
        for stage in ("hypotheses", "prediction", "observ", "verdict"):
            self.assertIn(stage, html)
        self.assertLess(html.index("prediction"), html.index("verdict"))

    def test_both_predictions_are_shown(self):
        html = self._html()
        self.assertIn("all indexes present", html)
        self.assertIn("cust_idx absent", html)

    def test_the_observation_is_shown(self):
        self.assertIn("orders_idx BTREE active", self._html())

    def test_the_winner_is_marked_and_the_loser_is_not(self):
        html = self._html()
        self.assertIn('data-verdict="supported"', html)
        self.assertIn('data-verdict="refuted"', html)

    def test_resolution_and_basis_are_stated(self):
        html = self._html()
        self.assertIn("RESOLVED_BY_EXPERIMENT", html)
        self.assertIn("environment outcome", html)

    def test_unresolved_renders_human_required_without_a_winner(self):
        html = self._html("sample_unresolved.json")
        self.assertIn("HUMAN_REQUIRED", html)
        self.assertNotIn('data-verdict="supported"', html)

    def test_has_a_title_tag(self):
        self.assertIn("<title>Ladder</title>", self._html(title="Ladder"))


class TestCli(unittest.TestCase):
    def test_cli_writes_the_output_file(self):
        out = Path("out_flow.html")
        proc = subprocess.run([sys.executable, "flow.py", "sample_flow.json", str(out)],
                              capture_output=True, text=True)
        self.assertEqual(proc.returncode, 0, proc.stderr)
        self.assertIn("RESOLVED_BY_EXPERIMENT", out.read_text(encoding="utf-8"))


if __name__ == "__main__":
    unittest.main()

